import config from "../../app.config";

/**
 * These assert the manifest entries that put dosya.dev in Android's "Open with"
 * chooser and share sheet. They exist because nothing else can catch their
 * removal: `android/` is gitignored and regenerated by prebuild, the app builds
 * and runs perfectly without them, and every other test still passes. The only
 * symptom is the app silently missing from the chooser on a device.
 *
 * The short-name assertions below are not style preferences. Expo's prebuild
 * prepends "android.intent.action." / "android.intent.category." when it writes
 * the manifest, so a fully-qualified name here is emitted DOUBLED - a filter
 * that is valid XML, ships without complaint, and matches nothing Android will
 * ever send. That exact mistake was made writing this feature and only surfaced
 * by reading the generated manifest.
 */
describe("android intent filters", () => {
  const filters = config.android?.intentFilters ?? [];

  const byAction = (action: string) => filters.filter((f) => f.action === action);
  /** Filters for https links (the TV sign-in universal link), as opposed to files. */
  const isWebLink = (f: (typeof filters)[number]) => ([] as { scheme?: string }[]).concat(f.data ?? []).some((d) => d.scheme === "https");
  const fileViews = () => byAction("VIEW").filter((f) => !isWebLink(f));

  it("claims VIEW for content:// URIs so the app appears under 'Open with'", () => {
    const view = fileViews();
    expect(view).toHaveLength(1);
    expect(view[0].category).toContain("DEFAULT");
    // Without scheme "content" this filter matches nothing a file manager sends:
    // SAF hands out content:// URIs exclusively, never file://.
    expect(view[0].data).toEqual(
      expect.arrayContaining([expect.objectContaining({ scheme: "content", mimeType: "*/*" })]),
    );
  });

  it("also claims VIEW for file:// URIs from older file managers", () => {
    // Pre-SAF and some OEM file managers still fire ACTION_VIEW with a file://
    // URI. The native receiver accepts that scheme already; without the
    // filter entry those apps simply never list dosya.dev.
    const view = fileViews();
    expect(view[0].data).toEqual(
      expect.arrayContaining([expect.objectContaining({ scheme: "file", mimeType: "*/*" })]),
    );
  });

  it("claims SEND and SEND_MULTIPLE so the app appears in the share sheet", () => {
    for (const action of ["SEND", "SEND_MULTIPLE"]) {
      const found = byAction(action);
      expect(found).toHaveLength(1);
      expect(found[0].category).toContain("DEFAULT");
      expect(found[0].data).toEqual(
        expect.arrayContaining([expect.objectContaining({ mimeType: "*/*" })]),
      );
    }
  });

  it("never writes a fully-qualified action or category name", () => {
    // The regression guard. Prefixing here is silently doubled by prebuild.
    for (const f of filters) {
      expect(f.action).not.toMatch(/^android\.intent\./);
      for (const c of f.category ?? []) expect(c).not.toMatch(/^android\.intent\./);
    }
  });

  it("does not autoVerify the file and share filters", () => {
    // autoVerify triggers App Links domain verification, which applies to http(s)
    // links. These carry no host, so verification could only ever fail - noisy in
    // logcat and confusing to debug.
    for (const f of filters.filter((x) => !isWebLink(x))) expect(f.autoVerify).toBeFalsy();
  });

  it("opens only the TV sign-in link from app.dosya.dev, as a verified App Link", () => {
    // The dosya TV app's QR code is https://app.dosya.dev/tv?code=... (app/tv.tsx).
    // Any wider path would pull every app.dosya.dev link out of the browser.
    const web = filters.filter(isWebLink);
    expect(web).toHaveLength(1);
    expect(web[0]).toEqual({
      action: "VIEW",
      autoVerify: true,
      category: ["DEFAULT", "BROWSABLE"],
      data: [{ scheme: "https", host: "app.dosya.dev", pathPrefix: "/tv" }],
    });
  });

  it("leaves the dosya:// scheme registered for OAuth callbacks", () => {
    // The share filters are additive. If a future edit replaces `scheme` with
    // intentFilters, dosya://auth/callback stops resolving and OAuth sign-in
    // breaks with an "Unmatched Route" - see the inOAuthCallback note in
    // app/_layout.tsx.
    expect(config.scheme).toBe("dosya");
  });
});
